const nand = (a, b) => (a && b) ? 0 : 1;
const not = a => nand(a, a);
const and = (a, b) => not(nand(a, b));
const or = (a, b) => nand(not(a), not(b));
const xor = (a, b) => {
  const n1 = nand(a, b);
  return nand(nand(a, n1), nand(b, n1));
};

console.log('a b | NOT(a) AND OR XOR');
for (const a of [0, 1])
  for (const b of [0, 1])
    console.log(a, b, '|', not(a), and(a, b), or(a, b), xor(a, b));
